import { Component, OnInit, OnDestroy, HostListener, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { Subject } from 'rxjs';
import { takeUntil, finalize } from 'rxjs/operators';
import { ProductService } from '../../services/product.service';
import { CategoryService } from '../../services/category.service';
import { CartService } from '../../services/cart.service';
import { ApiProduct, getPrimaryImage, getDiscountPercent, isProductInStock } from '../../models/api-product.model';
import { Category } from '../../models/category.model';
import { FlexCarouselItem } from '../../components/flex-carousel/flex-carousel.component';
import { DriftItem } from '../../shared/drift-wall/drift-wall.component';
import { ModelViewerComponent } from '../../components/model-viewer/model-viewer.component';
import { OutfitItem, OutfitRole } from '../../shared/outfit-scene/outfit-scene.component';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit, OnDestroy {
  // ── State ────────────────────────────────────────────────────────────────
  featuredProducts: ApiProduct[] = [];
  featuredProduct: ApiProduct | null = null;
  /** Recent products used for "New Arrivals" display (sorted by created_at desc by backend). */
  newArrivals: ApiProduct[] = [];
  categories: Category[] = [];
  /** Memoized gallery items – computed once when categories load. */
  categoryGalleryItems: { id: string; src: string; alt: string; label: string }[] = [];

  isLoadingFeatured = false;
  isLoadingArrivals = false;
  isLoadingCategories = false;
  featuredError: string | null = null;
  arrivalsError: string | null = null;

  // ── 3D Fitting Room Banner ───────────────────────────────────────────────
  @ViewChild('bannerViewer') bannerViewer?: ModelViewerComponent;
  bannerModelPath = 'assets/3dmodel/new/Meshy_AI_Prism_Glow_Bomber_1017114106_texture.glb';
  bannerRotating = true;
  bannerColorIndex = 0;
  bannerColors = [
    { name: 'Original', hex: 0xffffff },
    { name: 'Cyber Neon', hex: 0x39ff14 },
    { name: 'Electric Cyan', hex: 0x00e5ff },
    { name: 'Hyper Pink', hex: 0xff007f },
    { name: 'Liquid Gold', hex: 0xffd700 }
  ];

  // ── 3D Outfit Scene ──────────────────────────────────────────────────────
  // Order in array doesn't matter — layout is driven by role (shoes→bottom→top)
  outfitItems: OutfitItem[] = [
    {
      path:  'assets/3dmodel/complite/Meshy_AI_White_Adidas_Samba_Sn_1022112041_texture.glb',
      label: 'White Adidas Samba',
      role:  'shoes',
      tweak: 1.0
    },
    {
      path:  'assets/3dmodel/complite/Meshy_AI_Wide_Leg_Blue_Jeans_1022111857_texture.glb',
      label: 'Wide Leg Blue Jeans',
      role:  'bottom',
      tweak: 1.0
    },
    {
      path:  'assets/3dmodel/complite/Meshy_AI_White_Short_Sleeve_Bu_1022111329_texture.glb',
      label: 'White Short Sleeve Shirt',
      role:  'top',
      tweak: 1.0
    }
  ];

  /** Selected piece roles: all 3 selected by default */
  selectedOutfitRoles = new Set<OutfitRole>(['shoes', 'bottom', 'top']);
  /** Filtered items passed to app-outfit-scene */
  activeOutfitItems: OutfitItem[] = [...this.outfitItems];

  isPieceSelected(role: OutfitRole): boolean {
    return this.selectedOutfitRoles.has(role);
  }

  toggleOutfitPiece(role: OutfitRole): void {
    if (this.selectedOutfitRoles.has(role)) {
      this.selectedOutfitRoles.delete(role);
    } else {
      this.selectedOutfitRoles.add(role);
    }
    this.activeOutfitItems = this.outfitItems.filter(item => this.selectedOutfitRoles.has(item.role));
  }

  toggleBannerRotation(): void {
    this.bannerRotating = !this.bannerRotating;
  }

  resetBannerView(): void {
    if (this.bannerViewer) {
      this.bannerViewer.resetCamera();
    }
    this.bannerRotating = true;
  }

  cycleBannerColor(): void {
    this.bannerColorIndex = (this.bannerColorIndex + 1) % this.bannerColors.length;
    const selected = this.bannerColors[this.bannerColorIndex];
    if (this.bannerViewer) {
      this.bannerViewer.changeColor(selected.hex);
    }
  }

  // Slider state (REMOVED – FlexCarousel manages this internally)
  // currentSlide / sliderInterval removed

  // Favorites (localStorage, presentation only)
  favorites: { [productId: string]: boolean } = {};

  // ── Veil / mobile state ──────────────────────────────────────────────────
  veilFailed = false;
  isMobile   = typeof window !== 'undefined' && window.innerWidth <= 768;

  // ── DriftWall ────────────────────────────────────────────────────────────
  /** Memoized DriftItem array – rebuilt once after products load. */
  private _driftItems: DriftItem[] = [];
  private _driftItemsSrc: ApiProduct[] = [];

  get driftItems(): DriftItem[] { return this._driftItems; }

  get favoriteIdsSet(): Set<string> {
    return new Set(Object.keys(this.favorites).filter(k => this.favorites[k]));
  }

  get driftColumns(): number {
    const w = typeof window !== 'undefined' ? window.innerWidth : 1400;
    if (w >= 1200) return 5;
    if (w >= 768)  return 3;
    return 2;
  }

  get driftTileWidth(): number  { return this.isMobile ? 150 : 200; }
  get driftTileHeight(): number { return this.isMobile ? 200 : 270; }

  // Hardcoded static content (not connected to backend — kept as-is)
  collections = [
    { id: 'street-essentials', name: 'Street Essentials', image: 'assets/collections/essentials.jpg', description: 'Core pieces for everyday wear', itemCount: 45, startingPrice: 39.99 },
    { id: 'premium-collection', name: 'Premium Collection', image: 'assets/collections/premium.jpg', description: 'High-end materials and craftsmanship', itemCount: 28, startingPrice: 129.99 },
    { id: 'limited-edition', name: 'Limited Edition', image: 'assets/collections/limited.jpg', description: 'Exclusive drops available for limited time', itemCount: 15, startingPrice: 89.99 }
  ];
  testimonials = [
    { name: 'FRANKLIN', location: 'Los Santos', avatar: 'assets/avatars/franklin.jpg', rating: 5, text: 'The 3D fitting room changed how I shop. No more returns!', product: 'Vinewood Jacket' },
    { name: 'TREVOR', location: 'Sandy Shores', avatar: 'assets/avatars/trevor.jpg', rating: 4, text: 'Best streetwear in the city. Quality is unmatched.', product: 'Desert Cargos' },
    { name: 'MICHAEL', location: 'Rockford Hills', avatar: 'assets/avatars/michael.jpg', rating: 5, text: 'Premium quality meets street style. My go-to shop.', product: 'Executive Hoodie' }
  ];

  private destroy$ = new Subject<void>();

  constructor(
    private router: Router,
    private productService: ProductService,
    private categoryService: CategoryService,
    private cartService: CartService
  ) {}

  ngOnInit(): void {
    this.loadFeaturedProducts();
    this.loadRecentProducts();
    this.loadCategories();
    this.loadFavorites();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  // ── Data loading ─────────────────────────────────────────────────────────

  loadFeaturedProducts(): void {
    this.isLoadingFeatured = true;
    this.featuredError = null;
    this.productService
      .getFeaturedProducts(6)
      .pipe(takeUntil(this.destroy$), finalize(() => (this.isLoadingFeatured = false)))
      .subscribe({
        next: (res) => {
          if (res.items.length > 0) {
            // Normal path – backend has is_featured=true products
            this.featuredProducts = res.items;
            this.featuredProduct  = res.items[0] ?? null;
            this.veilFailed       = false;
            this._buildDriftItems();
          } else {
            // Fallback – no product is marked is_featured in the DB yet;
            // show the most recent products so the wall is never empty.
            this.productService
              .getRecentProducts(8)
              .pipe(takeUntil(this.destroy$))
              .subscribe({
                next: (recent) => {
                  this.featuredProducts = recent.items;
                  this.featuredProduct  = recent.items[0] ?? null;
                  this.veilFailed       = false;
                  this._buildDriftItems();
                },
                error: (err: Error) => { this.featuredError = err.message; },
              });
          }
        },
        error: (err: Error) => {
          this.featuredError = err.message;
        },
      });
  }

  loadRecentProducts(): void {
    this.isLoadingArrivals = true;
    this.arrivalsError = null;
    this.productService
      .getRecentProducts(20)
      .pipe(takeUntil(this.destroy$), finalize(() => (this.isLoadingArrivals = false)))
      .subscribe({
        next: (res) => {
          this.newArrivals = this.shuffleAndDiversifyProducts(res.items);
        },
        error: (err: Error) => {
          this.arrivalsError = err.message;
        },
      });
  }

  private shuffleAndDiversifyProducts(items: ApiProduct[]): ApiProduct[] {
    if (!items || items.length <= 2) return items;

    // Fisher-Yates random shuffle
    const list = [...items];
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }

    // Secondary pass to prevent consecutive items of identical category or type
    for (let i = 0; i < list.length - 1; i++) {
      const catA = list[i].category?.name?.toLowerCase() || '';
      const catB = list[i + 1].category?.name?.toLowerCase() || '';
      const nameA = list[i].name?.toLowerCase() || '';
      const nameB = list[i + 1].name?.toLowerCase() || '';

      const isSameCategory = catA && catA === catB;
      const isSameType = nameA.slice(0, 4) === nameB.slice(0, 4);

      if (isSameCategory || isSameType) {
        const swapIdx = list.findIndex((p, idx) => {
          if (idx <= i + 1) return false;
          const catC = p.category?.name?.toLowerCase() || '';
          return catC !== catA;
        });
        if (swapIdx !== -1) {
          [list[i + 1], list[swapIdx]] = [list[swapIdx], list[i + 1]];
        }
      }
    }

    return list;
  }

  loadCategories(): void {
    this.isLoadingCategories = true;
    this.categoryService
      .getCategories()
      .pipe(takeUntil(this.destroy$), finalize(() => (this.isLoadingCategories = false)))
      .subscribe({
        next: (cats) => {
          this.categories = cats;
          this.categoryGalleryItems = cats.map((c) => ({
            id: c.id,
            src: c.image_url || this.makeCategoryPlaceholder(c.name),
            alt: c.name,
            label: c.name,
          }));
        }
      });
  }

  private makeCategoryPlaceholder(name: string): string {
    const initials = name.split(' ').slice(0, 2).map((w) => w[0]?.toUpperCase() || '').join('');
    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='120' height='150' viewBox='0 0 120 150'>` +
      `<rect width='120' height='150' fill='#1a1a1a'/>` +
      `<text x='60' y='70' font-family='sans-serif' font-size='28' fill='#39ff14' font-weight='bold' text-anchor='middle' dominant-baseline='middle'>${initials}</text>` +
      `<text x='60' y='105' font-family='sans-serif' font-size='10' fill='#888888' text-anchor='middle' letter-spacing='2'>${name.toUpperCase().slice(0, 12)}</text>` +
      `</svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
  }

  // ── DriftWall helpers ────────────────────────────────────────────────────

  private _buildDriftItems(): void {
    const prods = this.featuredProducts;
    if (prods === this._driftItemsSrc) return; // no change
    this._driftItemsSrc = prods;
    this._driftItems = prods.map((p, i) => ({
      id:             p.id,
      image:          this.getProductImage(p),
      title:          p.name,
      price:          Number(p.price),
      comparePrice:   p.compare_price ? Number(p.compare_price) : null,
      category:       this.getCategoryName(p),
      inStock:        this.isInStock(p),
      discountPercent: this.getDiscountPercent(p),
      rank:           i + 1,
      raw:            p,
    }));
  }

  // ── Helpers (shared utilities from model) ────────────────────────────────

  getProductImage(product: ApiProduct): string {
    return getPrimaryImage(product) ?? 'assets/images/home/67d42860e79a4.png';
  }

  getDiscountPercent(product: ApiProduct): number {
    return getDiscountPercent(product);
  }

  isInStock(product: ApiProduct): boolean {
    return isProductInStock(product);
  }

  getCategoryName(product: ApiProduct): string {
    return product.category?.name ?? '';
  }

  // ── Navigation ───────────────────────────────────────────────────────────

  goToTryOn(): void { this.router.navigate(['/try-on']); }
  goToShop(): void { this.router.navigate(['/shop']); }
  goToProduct(productId: string): void { this.router.navigate(['/product', productId]); }
  goToTutorial(): void { this.router.navigate(['/tutorial']); }

  goToCategory(categoryId: string): void {
    this.router.navigate(['/shop'], { queryParams: { category_id: categoryId } });
  }

  goToCollection(collectionId: string): void {
    this.router.navigate(['/shop'], { queryParams: { collection: collectionId } });
  }

  // ── Cart ─────────────────────────────────────────────────────────────────

  addToCart(product: ApiProduct): void {
    if (!this.isInStock(product)) return;
    // No variant selected from the home page — add with no variant (null)
    this.cartService.addToCart(product, 1, null);
  }

  tryOnProduct(product: ApiProduct): void {
    this.router.navigate(['/try-on'], { queryParams: { productId: product.id } });
  }

  // ── Favorites ────────────────────────────────────────────────────────────

  toggleFavorite(productId: string): void {
    this.favorites[productId] = !this.favorites[productId];
    this.saveFavorites();
  }
  isFavorite(productId: string): boolean { return !!this.favorites[productId]; }
  loadFavorites(): void {
    const saved = localStorage.getItem('home_favorites');
    if (saved) this.favorites = JSON.parse(saved);
  }
  saveFavorites(): void {
    localStorage.setItem('home_favorites', JSON.stringify(this.favorites));
  }

  // ── FlexCarousel helpers ──────────────────────────────────────────────────

  getCarouselItems(): FlexCarouselItem[] {
    return this.newArrivals.map(p => ({
      src: this.getProductImage(p),
      alt: p.name,
      title: p.name,
      subtitle: this.getCategoryName(p) + (p.material ? ' · ' + p.material : ''),
      productId: p.id,
      price: (+p.price).toFixed(2),
      category: this.getCategoryName(p),
    }));
  }

  onCarouselItemClick(event: { index: number; item: FlexCarouselItem }): void {
    const item = event.item as any;
    if (item._addToCart) {
      // ADD TO CART action from carousel action bar
      const product = this.newArrivals[event.index];
      if (product) this.addToCart(product);
    } else {
      // QUICK VIEW — navigate to product
      if (event.item.productId) this.goToProduct(event.item.productId);
    }
  }

  // ── Slider (REMOVED — FlexCarousel is self-contained) ────────────────────
  // startSlider / nextSlide / prevSlide / goToSlide removed

  @HostListener('window:resize')
  onResize(): void { this.isMobile = window.innerWidth <= 768; }
}